        dest[destOffset + 4] = 2.0f * Math.fma(dqRX, dqRY, _t2);
        dest[destOffset + 5] = Math.fma(-2.0f, _t4, _t6);
        dest[destOffset + 6] = Math.fma(-2.0f, dqRX * dqRW, 2.0f * _t5);
